const { sequelize, Sequelize } = require("../db");

/* One-click login — one-time codes generated by the admin panel.
   Codes are single-use (atomic claim on redemption) and expire in 7 days. */
const LoginCode = sequelize.define(
  "LoginCode",
  {
    id: { type: Sequelize.INTEGER.UNSIGNED, primaryKey: true, autoIncrement: true },
    legacyId: { type: Sequelize.CHAR(24), field: "legacy_id" },
    code: { type: Sequelize.CHAR(48), unique: true },
    user: { type: Sequelize.INTEGER.UNSIGNED, field: "user_id" },
    used: { type: Sequelize.BOOLEAN, defaultValue: false },
    usedAt: { type: Sequelize.DATE, defaultValue: null, field: "used_at" },
    expiresAt: { type: Sequelize.DATE, field: "expires_at" },
  },
  { tableName: "login_codes", underscored: true }
);

module.exports = LoginCode;
